// The workbench (docs/10 §9.7): lookup prints what `keypath lookup --layout L
// --top N` prints, type what `keypath type --layout L` prints, on fixtures
// tools/build_data.py generated by running the Python CLI; pyrepr quotes as
// Python's repr does.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { ROOT, engine, readJson, readJsonl } from "./helpers.js";
import { parseHtml, elements, byId } from "./html.js";
import { pyrepr } from "../assets/js/engine/pyrepr.js";

const lookups = readJsonl("tests/fixtures/workbench-lookup.jsonl.gz");
const types = readJsonl("tests/fixtures/workbench-type.jsonl.gz");
const rules = readJson("tests/fixtures/workbench-rules.json");
const registry = readJson("data/registry.json");

const LIT = rules.lit;
const RULE_RE = Object.fromEntries(Object.entries(rules.rules)
  .map(([name, pattern]) => [name, new RegExp(`^${pattern.replaceAll("LIT", LIT)}$`, "u")]));
const QUOTES = {
  single: c => c.includes("'") && !c.includes('"'),
  double: c => c.includes('"') && !c.includes("'"),
  both: c => c.includes("'") && c.includes('"'),
  backslash: c => c.includes("\\"),
};

/** (chunk, surface name, violated rule or null) per block of lookup's text. */
function blocks(text) {
  return text.split("\n\n").map(block => {
    const [head, ...rest] = block.split("\n");
    const m = head.match(/^([\x21-\x7e]*) · (\([a-z]+, [a-z_]+\)) · well-formed: (yes|no)$/);
    assert.ok(m, head);
    return { chunk: m[1], surface: m[2], rule: m[3] === "no" ? rest[0].replace(/^ {2}violated rule: /, "") : null };
  });
}

test("the workbench keyboards are docs/10 §9.7's, each with its surfaces in registry order", () => {
  assert.deepEqual(registry.workbench.map(w => w.layout), rules.layouts);
  // M14's keyboards, Vietnamese Telex and VNI (M15), ETen and Jyutping
  // (M16), each after its twin as on the page's chips, and Greek (M17); no Japanese
  assert.deepEqual(rules.layouts, ["zh_daqian", "zh_eten", "zh_pinyin", "zh_jyutping", "zh_cangjie", "zh_quick", "ko_dubeolsik",
    "ru_jcuken", "es_accent", "en_identity", "vi_telex", "vi_vni", "el_greek"]);
  for (const { layout, surfaces } of registry.workbench) {
    assert.deepEqual(surfaces, registry.kp1Surfaces.filter(([, l]) => l === layout), layout);
    assert.ok(surfaces.every(([language]) => language !== "ja"), layout);
  }
  assert.deepEqual(registry.workbench.find(w => w.layout === "ko_dubeolsik").surfaces, [["ko", "ko_dubeolsik"], ["zh", "ko_dubeolsik"]]);
});

test("lookup prints what keypath lookup prints, on every fixture", async () => {
  assert.ok(lookups.length >= 500, `${lookups.length} lookup fixtures`);
  assert.ok(lookups.filter(r => !r.wellFormed).length >= 100);
  assert.deepEqual(new Set(lookups.map(r => r.layout)), new Set(rules.layouts));
  const e = await engine();
  for (const r of lookups) {
    const got = await e.lookup({ layout: r.layout, chunks: r.chunks, top: r.top });
    assert.equal(got.ok, true, r.id);
    assert.equal(got.text, r.output, `${r.id}: ${r.layout} ${JSON.stringify(r.chunks)} top ${r.top}`);
    assert.equal(got.wellFormed, r.wellFormed, r.id);
    assert.equal(got.blocks.map(b => b.text).join("\n\n"), got.text);
  }
});

test("type prints what keypath type prints, on every fixture", async () => {
  assert.ok(types.length >= 200, `${types.length} type fixtures`);
  assert.deepEqual(new Set(types.map(r => r.layout)), new Set(rules.layouts));
  const e = await engine();
  for (const r of types) {
    const got = await e.type({ layout: r.layout, text: r.input });
    assert.equal(got.ok, true, r.id);
    assert.equal(got.text, r.output, `${r.id}: ${r.layout} ${JSON.stringify(r.input)}`);
    assert.equal(got.sections.map(s => s.text).join("\n"), got.text);
  }
});

test("the fixtures reach every violated-rule template of every surface, with chunks holding ', \", both, and \\", () => {
  const covered = {}, quoted = {};
  for (const r of lookups) {
    for (const b of blocks(r.output)) {
      if (b.rule === null) continue;
      const names = rules.surfaces[b.surface].filter(name => RULE_RE[name].test(b.rule));
      assert.equal(names.length, 1, `${b.surface}: ${b.rule}`);
      (covered[b.surface] ??= new Set()).add(names[0]);
      for (const [cls, holds] of Object.entries(QUOTES)) if (holds(b.chunk)) (quoted[b.surface] ??= new Set()).add(cls);
    }
  }
  const surfaces = registry.workbench.flatMap(w => w.surfaces.map(([l, k]) => `(${l}, ${k})`));
  assert.deepEqual(Object.keys(rules.surfaces).sort(), [...surfaces].sort());
  for (const s of surfaces) {
    assert.deepEqual([...covered[s]].sort(), [...rules.surfaces[s]].sort(), s);
    assert.deepEqual([...quoted[s]].sort(), Object.keys(QUOTES).sort(), s);
  }
});

test("pyrepr is Python's repr for every value a message quotes, and more", () => {
  const pairs = readJson("tests/fixtures/pyrepr.json");
  assert.ok(pairs.length >= 400);
  for (const [s, repr] of pairs) assert.equal(pyrepr(s), repr, JSON.stringify(s));
  // the rule (docs/10 §9.7), spelled out
  assert.equal(pyrepr("tgno"), "'tgno'");
  assert.equal(pyrepr("it's"), `"it's"`);
  assert.equal(pyrepr(`say "hi"`), `'say "hi"'`);
  assert.equal(pyrepr(`'"`), `'\\'"'`);
  assert.equal(pyrepr("a\\b"), "'a\\\\b'");
  assert.equal(pyrepr("ㄋㄧˇ"), "'ㄋㄧˇ'");
});

test("docs/10 §8.2-§8.3 goldens", async () => {
  const e = await engine();
  const look = async (layout, chunk) => (await e.lookup({ layout, chunks: [chunk] })).text;
  assert.match(await look("zh_cangjie", "tgno"), /\n {2}candidates: 3\n {2}0:歡 1:莰 2:羑$/);
  assert.match(await look("zh_cangjie", "ykhaf"), /\n {2}candidates: 6\n/);
  assert.match(await look("zh_quick", "of"), /\n {2}candidates: 62\n {2}0:你 /);
  assert.match(await look("zh_daqian", "su3"), /^su3 · \(zh, zh_daqian\) · well-formed: yes\n {2}reading: ㄋㄧˇ \/ ni3\n {2}candidates: 32\n {2}0:你 /);
  const typed = async (layout, text) => (await e.type({ layout, text })).text;
  assert.equal(await typed("zh_cangjie", "明天"), "(zh, zh_cangjie)\n明 ab 0/1\n天 mk 0/1");
  assert.equal(await typed("zh_quick", "明天"), "(zh, zh_quick)\n明 ab 0/14\n天 mk 1/60");
  // docs/10 §4.3-§4.4: ETen reads as Dàqiān does (7 is ㄑ), Jyutping as the syllable, with its pun
  assert.match(await look("zh_eten", "ne3"), /^ne3 · \(zh, zh_eten\) · well-formed: yes\n {2}reading: ㄋㄧˇ \/ ni3\n {2}candidates: 32\n {2}0:你 /);
  assert.match(await look("zh_eten", "7"), /^7 · \(zh, zh_eten\) · well-formed: yes\n {2}reading: ㄑ \/ /);
  assert.match(await look("zh_eten", "3"), /\n {2}violated rule: unit '3' is a bare tone key$/);
  assert.match(await look("zh_jyutping", "nei5"), /^nei5 · \(zh, zh_jyutping\) · well-formed: yes\n {2}reading: nei5\n {2}candidates: 14\n {2}0:你 /);
  assert.match(await look("zh_jyutping", "hou2"), /\n {2}candidates: 2\n {2}0:好 1:/);
  assert.match(await look("zh_pinyin", "hou2"), /\n {2}candidates: 21\n {2}0:侯 /);
  assert.match(await look("zh_jyutping", "si1"), /\n {2}candidates: 68\n {2}0:司 .* 7:詩 /);
  assert.match(await look("zh_pinyin", "nei5"), /well-formed: no\n/);
  assert.match(await look("zh_jyutping", "nei"), /\n {2}violated rule: unit 'nei' does not end in a tone digit 1-6$/);
  assert.equal(await typed("zh_eten", "你好"), "(zh, zh_eten)\n你 ne3 0/32\n好 hz3 0/4");
  assert.equal(await typed("zh_jyutping", "你好"), "(zh, zh_jyutping)\n你 nei5 0/14\n好 hou2 0/2");
  // docs/10 §7.1: Greek reads a word left to right; a dead key must be followed by a vowel it accents
  assert.equal(await look("el_greek", "kalhm;era"), "kalhm;era · (el, el_greek) · well-formed: yes\n  reading: καλημέρα\n"
    + "  candidates: 1 (identity: the unit is its reading; a key carries no homophone_index)\n  0:καλημέρα");
  const rule = "on el_greek it must be followed by a vowel key it combines with";
  assert.match(await look("el_greek", "kal;b"), new RegExp(`\n {2}violated rule: dead key ';' \\(΄\\) at position 3 of unit 'kal;b' is followed by 'b'; ${rule} \\(a e h i o y v\\)$`));
  assert.match(await look("el_greek", "W"), new RegExp(`\n {2}violated rule: dead key 'W' \\(΅\\) at position 0 of unit 'W' ends the unit; ${rule} \\(i y\\)$`));
  assert.match(await look("el_greek", "q"), /\n {2}violated rule: unit 'q' contains 'q', which is outside the el_greek alphabet$/);
  for (const [word, keys] of [["καλημέρα", "kalhm;era"], ["ευχαριστώ", "eyxarist;v"], ["θάλασσα", "u;alassa"], ["ωραίος", "vra;iow"],
    ["καΐκι", "kaWiki"], ["ψυχή", "cyx;h"], ["σκύλος", "sk;ylow"], ["προϊόν", "pro:i;on"]]) {
    assert.equal(await typed("el_greek", word), `(el, el_greek)\n${word} ${keys} -`, word);
    assert.match(await look("el_greek", keys), new RegExp(`\n {2}reading: ${word}\n`), keys);
  }
  assert.equal(await typed("el_greek", "ΟΔΟΣ"), "(el, el_greek)\nοδος odow -");
});

test("a chunk is printable ASCII other than space; anything else is refused, naming the code point", async () => {
  const e = await engine();
  for (const [chunks, index, codePoint] of [[["su3", "é"], 1, "U+00E9"], [["a b"], 0, "U+0020"], [["\t"], 0, "U+0009"],
    [["中"], 0, "U+4E2D"], [["tgno\u3000"], 0, "U+3000"], [["😀"], 0, "U+1F600"], [["\ud800"], 0, "U+D800"], [["x\u007f"], 0, "U+007F"]]) {
    assert.deepEqual(await e.lookup({ layout: "zh_daqian", chunks }), { ok: false, reason: "badChunk", index, codePoint }, JSON.stringify(chunks));
  }
  assert.deepEqual(await e.lookup({ layout: "zh_daqian", chunks: [3] }), { ok: false, reason: "badChunk", index: 0, codePoint: null });
  // every printable ASCII key is a chunk (the empty chunk too: keypath lookup reads it)
  const all = Array.from({ length: 0x7e - 0x20 }, (_, i) => String.fromCharCode(0x21 + i));
  const r = await e.lookup({ layout: "ru_jcuken", chunks: [...all, ""] });
  assert.equal(r.ok, true);
  assert.equal(r.blocks.length, all.length + 1);
});

test("lookup needs chunks and a non-negative whole top; type needs text in Unicode 14", async () => {
  const e = await engine();
  for (const chunks of [undefined, [], "tgno", null]) {
    assert.deepEqual(await e.lookup({ layout: "zh_cangjie", chunks }), { ok: false, reason: "noChunks" });
  }
  for (const top of [-1, 1.5, "10", NaN, Infinity, null, 2 ** 53]) {
    assert.deepEqual(await e.lookup({ layout: "zh_cangjie", chunks: ["tgno"], top }), { ok: false, reason: "badTop" }, String(top));
  }
  assert.equal((await e.lookup({ layout: "zh_cangjie", chunks: ["tgno"] })).text,
    (await e.lookup({ layout: "zh_cangjie", chunks: ["tgno"], top: 10 })).text, "top defaults to 10");
  assert.deepEqual(await e.type({ layout: "en_identity" }), { ok: false, reason: "noText" });
  assert.deepEqual(await e.type({ layout: "en_identity", text: "a͸" }), { ok: false, reason: "newerUnicode", codePoint: "U+0378" });
  assert.deepEqual(await e.type({ layout: "zh_daqian", text: "你\ud800" }), { ok: false, reason: "newerUnicode", codePoint: "U+D800" });
});

test("the page's keyboard picker offers exactly the workbench keyboards, picks none, and has no 'any'", () => {
  const doc = parseHtml(readFileSync(join(ROOT, "index.html"), "utf8"));
  const section = byId(doc, "workbench");
  const inputs = elements(section).filter(e => e.tag === "input" && e.attrs.type === "radio");
  assert.deepEqual(inputs.map(e => e.attrs.value), registry.workbench.map(w => w.layout));
  assert.ok(inputs.every(e => e.attrs.name === "wbkbd" && !("checked" in e.attrs)));
  const values = elements(section).filter(e => ["input", "option"].includes(e.tag)).map(e => e.attrs.value);
  assert.ok(!values.some(v => /^(any|all|auto|\*)$/i.test(v || "")), JSON.stringify(values));
  // the candidate counts it offers are whole numbers lookup takes
  const tops = elements(byId(doc, "wb-top")).filter(e => e.tag === "option").map(e => Number(e.attrs.value));
  assert.deepEqual(tops, [10, 50, 500]);
});
